from __future__ import annotations


def omega_trace(d: int) -> int:
    """Trace T = Tr(omega): 1 if d == 1 (mod 4) else 0."""
    return 1 if d % 4 == 1 else 0


def omega_norm(d: int) -> int:
    """Norm M = N(omega): (1 - d)//4 if d == 1 (mod 4) else -d."""
    if d % 4 == 1:
        return (1 - d) // 4
    return -d


def fundamental_disc(d: int) -> int:
    """Fundamental discriminant D_K: d if d == 1 (mod 4) else 4d."""
    return d if d % 4 == 1 else 4 * d


def disc_from_TM(t: int, m: int) -> int:
    """Algebraic core: discriminant of x^2 - T x + M is T^2 - 4M."""
    return t ** 2 - 4 * m


if __name__ == "__main__":
    for d in [-1, -2, -3, -7, -11, -15]:
        t, m = omega_trace(d), omega_norm(d)
        print(d, "->  T =", t, " M =", m,
              " T^2-4M =", disc_from_TM(t, m),
              " D_K =", fundamental_disc(d))
